INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, 'specialist_education', '2023-2024 АНО ДПО «НАДПО»<br>\n2024 Институт Психотерапии и Клинической Психологии (повышение квалификации)<br>\n2025 Московский Институт Милтона Эриксона (ДПДГ)<br>\n2025 по настоящее время МГИ Московский Гештальт Институт, 2 ступень');
INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, '_specialist_education', 'field_fp02_specialist_education');
INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, 'specialist_specialization', 'Психосоматика и телесная психотерапия<br>\nДессенсибилизация и переработка движением глаз<br>\nСертификат спецкурса «Психиатрия для психологов» от GATLA');
INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, '_specialist_specialization', 'field_fp02_specialist_specialization');
INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, 'specialist_principles', '<p>Дарья применяет методы и техники из нескольких психотерапевтических направлений: телесно-ориентированной терапии, гештальт терапии и метода EMDR/ДПДГ (дессенсибилизация и переработка движением глаз), что позволяет подобрать комплексный и индивидуализированный подход для улучшения психического состояния клиента.</p>');
INSERT INTO fp02_postmeta (post_id, meta_key, meta_value) VALUES (1033, '_specialist_principles', 'field_fp02_specialist_principles');
